function save(){try{localStorage.setItem(saveKey,JSON.stringify(state));$('#save-status').textContent='';}catch{$('#save-status').textContent=' · indisponible sur ce navigateur';$('#save-status').classList.add('storage-warning');}}
// ===== Apprentissage des attaques : jusqu'à 4 attaques connues, au-delà on choisit laquelle oublier =====
// state.moves[id] = {known:[noms], seen:niveau déjà traité}. Sans enregistrement : les 4 dernières attaques apprises (comme avant).
async function moveRecord(id){let r=state.moves[id];if(!r){const sp=await getSpecies(id);r=state.moves[id]={known:knownMoves(sp.learnset,lv(id).level),seen:lv(id).level,v:2};save();}return r;}
const knownNames=async id=>(await moveRecord(id)).known;
let learning=null;
function learnAll(){return learning||(learning=(async()=>{try{for(const id of [...state.team]){const sp=await getSpecies(id),r=await moveRecord(id),l=lv(id).level;
  const migrate=(r.v|0)<2;if(migrate){r.seen=0;}
  for(const [name,at] of sp.learnset){if(at<=r.seen||at>l||r.known.includes(name))continue;
    if(migrate){if(r.known.length<4){const d=(await getMoves([name]))[0];if(isUsable(d)){r.known.push(name);save();}}continue;}
    if(r.known.length<4){const d=(await getMoves([name]))[0];if(!isUsable(d))continue;r.known.push(name);save();continue;}
    {const d=(await getMoves([name]))[0];if(!isUsable(d))continue;}
    if(getPreferences().skipLearn)continue;const pick=await chooseMove(id,name);if(pick!==null){r.known[pick]=name;save();}}
  if(r.seen<l||r.v!==2){r.seen=Math.max(r.seen,l);r.v=2;save();}}}catch(e){console.error(e);}finally{learning=null;render();}})());}
function chooseMove(id,newName){return new Promise(async resolve=>{
  const r=state.moves[id],[nm,...cur]=await getMoves([newName,...r.known]),who=pool[id-1].name;
  const detail=m=>isUsable(m)?m.power<=0?`Statut · Préc. <b>${m.acc??'—'}</b>`:`${m.cls==='physical'?'Physique':'Spécial'} · Puiss. <b>${m.power}</b> · Préc. <b>${m.acc??'—'}</b>`:'Statut · <b>Effet à venir</b>';
  const card=(m,i,isNew)=>`<button class="learn-move${isNew?' is-new':''}" data-i="${i}" style="--tc:${typeColor(m.type)}" ${isNew?'disabled':''}><span class="learn-top"><b>${m.fr}</b><span class="type-badge" style="--tc:${typeColor(m.type)}">${TYPE_FR[m.type]||m.type}</span></span><small>${detail(m)}</small>${isNew?'':`<em>${i+1} · Oublier</em>`}</button>`;
  const d=document.createElement('dialog');d.className='learn';d.setAttribute('aria-label','Nouvelle attaque');
  d.innerHTML=`<div class="learn-box"><img src="${sprite(id)}" alt=""><h2>${who} veut apprendre ${nm.fr} !</h2><div class="learn-new">${card(nm,-1,true)}</div><p>Mais ${who} connaît déjà 4 attaques. Laquelle faut-il oublier ?</p><div class="learn-grid">${cur.map((m,i)=>card(m,i,false)).join('')}</div><button class="learn-skip">Ne pas apprendre ${nm.fr}</button></div>`;
  document.body.appendChild(d);
  const done=v=>{document.removeEventListener('keydown',onKey,true);d.close();d.remove();resolve(v);};
  const onKey=e=>{if(e.key>='1'&&e.key<='4'){const b=d.querySelector(`.learn-move[data-i="${+e.key-1}"]`);if(b){e.preventDefault();e.stopPropagation();done(+e.key-1);}}};
  d.addEventListener('click',e=>{const b=e.target.closest('.learn-move:not(.is-new)');if(b){done(+b.dataset.i);return;}if(e.target.closest('.learn-skip'))done(null);});
  d.addEventListener('cancel',e=>{e.preventDefault();done(null);});document.addEventListener('keydown',onKey,true);
  d.showModal();d.querySelector('.learn-move:not(.is-new)')?.focus();});}
// Fenêtre de choix générique (objet à porter, CT à utiliser) : renvoie l'identifiant choisi ou null.
function pickDialog({id,title,intro,options,cancel='Annuler'}){return new Promise(resolve=>{
  const d=document.createElement('dialog');d.className='learn pick';d.setAttribute('aria-label',title);
  d.innerHTML=`<div class="learn-box"><img src="${sprite(id)}" alt=""><h2>${title}</h2><p>${intro}</p><div class="learn-grid">${options.map((o,i)=>`<button class="learn-move pick-opt" data-pick="${o.id}" style="--tc:${o.color||'#6ec1ff'}" ${o.disabled?'disabled':''}><span class="learn-top"><b>${o.name}</b>${o.badge||''}</span><small>${o.detail}</small>${o.note?`<em>${o.note}</em>`:''}</button>`).join('')||'<small>Rien à choisir pour le moment.</small>'}</div><button class="learn-skip">${cancel}</button></div>`;
  document.body.appendChild(d);
  const done=v=>{d.close();d.remove();resolve(v);};
  d.addEventListener('click',e=>{const b=e.target.closest('[data-pick]:not(:disabled)');if(b){done(b.dataset.pick);return;}if(e.target.closest('.learn-skip'))done(null);});
  d.addEventListener('cancel',e=>{e.preventDefault();done(null);});d.showModal();d.querySelector('[data-pick]:not(:disabled)')?.focus();});}
let pendingWild=null;
// Une espèce capturée pour la première fois arrive au niveau du Pokémon rencontré (dans la limite du palier de son stade et du plafond des badges).
function giveCatchLevel(id,wl){const min=minLevel(id),L=Math.max(min,Math.min(wl|0,maxLevel(id),levelCap(state.badges)));let total=0;for(let l=min;l<L;l++)total+=xpToNext(l);const b=Math.max(0,total-Math.max(0,(state.counts[id]||1)-1));if(b>0)state.xp[id]=b;}
function evoCheck(before){const e=teamEvolution(before,state.team);if(e)playEvolution({...e,fromName:pool[e.from-1].name,toName:pool[e.to-1].name,fromSrc:sprite(e.from,false),toSrc:sprite(e.to,false),reduced:state.reducedMotion});}
async function pickSwap(id,idx){const sp=await getSpecies(id),r=await moveRecord(id),l=lv(id).level;
  const names=[...new Set(sp.learnset.filter(([,at])=>at<=l).map(([n])=>n))];if(!names.length)return;
  const defs=await getMoves(names),cur=r.known[idx];
  const options=defs.map(m=>({id:m.name,name:m.fr,detail:(m.power>0?`${TYPE_FR[m.type]||m.type} · Puissance ${m.power}`:`${TYPE_FR[m.type]||m.type} · Statut`)+(m.acc?` · Précision ${m.acc}`:'')+(isUsable(m)?'':' · Effet à venir'),note:m.name===cur?'Attaque actuelle':r.known.includes(m.name)?'Déjà dans ses attaques':'',disabled:r.known.includes(m.name),color:typeColor(m.type)}));
  const pick=await pickDialog({id,title:`Changer ${r.known[idx]?(await getMoves([cur]))[0]?.fr||cur:'l’attaque'}`,intro:'Choisis parmi toutes les attaques déjà apprises par ce Pokémon.',options});
  if(!pick||pick===cur)return;r.known[idx]=pick;save();render();openProfile(id);}
async function pickHeld(id){const options=Object.values(ITEMS).filter(i=>i.kind==='held').map(i=>({id:i.id,name:i.name,detail:i.effect,note:freeCopies(state.inv,i.id)>0?`${freeCopies(state.inv,i.id)} libre${freeCopies(state.inv,i.id)>1?'s':''} dans ton sac`:'Aucun exemplaire libre · achète-en en boutique',disabled:freeCopies(state.inv,i.id)<1,color:'#ffc94a'}));
  const pick=await pickDialog({id,title:`Objet tenu par ${pool[id-1].name}`,intro:'Choisis l’objet à lui faire porter.',options});if(!pick)return;if(equipHeld(state,id,pick)){save();render();openProfile(id);}}
async function pickStone(id){const opts=stoneTargets(id).map(({stone,to})=>{const it=ITEMS[stone],has=stockOf(state.inv,stone),owned=!!state.counts[to];return{id:stone,name:`${it.name} → ${pool[to-1].name}`,detail:it.effect,note:owned?`${pool[to-1].name} est déjà dans ta collection`:has?`×${has} dans ton sac`:'Aucune dans ton sac · achète-en en boutique',disabled:owned||!has,color:'#ffd27c'};});
  const pick=await pickDialog({id,title:`Évolution de ${pool[id-1].name}`,intro:'La pierre est consommée. L’évolution rejoint ta collection et prend la place de sa forme précédente dans l’équipe.',options:opts});if(!pick)return;
  const to=ITEMS[pick].evolves[id];if(!state.counts[id]||state.counts[to]||stockOf(state.inv,pick)<1)return;
  state.inv.stock[pick]-=1;if(state.inv.stock[pick]<=0)delete state.inv.stock[pick];
  state.counts[to]=1;{const b=[...state.team];state.team=teamAfterCapture(state.team,to);setTimeout(()=>evoCheck(b),300);}
  if(state.inv.held[id]){state.inv.held[to]=state.inv.held[id];delete state.inv.held[id];}
  state.stats.evolutions=(state.stats.evolutions||0)+1;
  save();render();renderZones();openProfile(to);}
async function pickTm(id){const sp=await getSpecies(id),known=await knownNames(id),tms=Object.values(ITEMS).filter(i=>i.kind==='tm'&&stockOf(state.inv,i.id)>0);
  const mv=await getMoves(tms.map(t=>t.move));
  const options=tms.map((t,i)=>{const m=mv[i],ok=sp.machines?.includes(t.move),has=known.includes(t.move);return {id:t.id,name:m.fr,badge:`<span class="type-badge" style="--tc:${typeColor(m.type)}">${TYPE_FR[m.type]||m.type}</span>`,detail:isUsable(m)?`${m.cls==='physical'?'Physique':'Spécial'} · Puiss. <b>${m.power}</b> · Préc. <b>${m.acc??'—'}</b>`:'Statut · <b>Effet à venir</b>',note:has?'Déjà connue':ok?`${t.name.split(' · ')[0]} · ×${stockOf(state.inv,t.id)} dans ton sac`:'Incompatible avec ce Pokémon',disabled:!ok||has,color:typeColor(m.type)};});
  const pick=await pickDialog({id,title:`Une CT pour ${pool[id-1].name}`,intro:'La CT est consommée quand l’attaque est apprise.',options});if(!pick)return;
  const t=ITEMS[pick],r=await moveRecord(id);let at=r.known.length<4?r.known.length:await chooseMove(id,t.move);if(at===null)return;r.known[at]=t.move;useTm(state,pick);state.stats.tmUsed=(state.stats.tmUsed||0)+1;save();render();openProfile(id);}
const ownedSprite=id=>sprite(id,selectedShiny(state,id));
const fmt=n=>n.toLocaleString('fr-FR');
// Puissances compactes : 12,3 k · 45 M · 3,2 Md (milliards) · 1,5 Bn (billions), avec une médaille par palier.
const splitP=n=>{const f=v=>(v>=100?Math.round(v):Math.round(v*10)/10).toLocaleString('fr-FR');return n>=1e12?[f(n/1e12),'Bn']:n>=1e9?[f(n/1e9),'Md']:n>=1e6?[f(n/1e6),'M']:n>=1e4?[f(n/1e3),'k']:[n.toLocaleString('fr-FR'),''];};
const fmtP=n=>splitP(n).join(' ').trim();
const TIERS=[['#c98a52','#7a4a22','Bronze'],['#d7e2ea','#7d8f9c','Argent'],['#ffd25a','#b0771a','Or'],['#9ee8d6','#2f8f7c','Platine'],['#6fe3ff','#1d7fa8','Diamant'],['#ff8ae6','#a02f8c','Maître']];
const tierP=n=>powerRank(n);let medalId=0;
// Rangs de puissance = badges d'arène de Kanto, dans l'ordre (Roche, Cascade, Foudre, Prisme…) : la suite prolongera la série.
const BADGES=[['Roche',1],['Cascade',2],['Foudre',3],['Prisme',4],['Âme',5],['Marais',6]];
const badgeUrl=i=>`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/badges/${BADGES[i][1]}.png`;
const medal=(n,size)=>{const i=tierP(n);return `<img class="medal badge-img" src="${badgeUrl(i)}" width="${size}" height="${size}" alt="" aria-hidden="true">`;};
const powerBadge=(n,mini)=>{const [v,u]=splitP(n),t=tierP(n);return `<span class="pw${mini?' pw-mini':''}" style="--pc:${TIERS[t][0]}" title="Puissance ${fmt(n)} · ${TIERS[t][2]} · Badge ${BADGES[t][0]}">${medal(n,mini?26:52)}<span class="pw-txt"><small>Puissance</small><b>${v}</b><i>${u}</i></span></span>`;};
function bannerPower(n){const p=powerProgress(n),[v,u]=splitP(n),tier=TIERS[p.index],next=p.next===null?'Palier maximum':TIERS[p.index+1][2]+' à '+fmtP(p.next);return `<span class="power-panel" style="--pc:${tier[0]}">${medal(n,38)}<span class="power-panel-info"><span class="power-heading"><small>Puissance · ${tier[2]}</small><b>${v}<i>${u}</i></b></span><span class="power-progress" role="progressbar" aria-label="Progression du palier de puissance" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(p.percent*100)/100}"><span style="width:${p.percent}%"></span></span><span class="power-next">${next}${p.next===null?'':' · reste '+fmtP(p.remaining)}</span></span></span>`;}

const PR_COL=[['#d97a3a','#7a3412'],['#cbd5e1','#475569'],['#facc15','#854d0e'],['#2dd4bf','#115e59'],['#38bdf8','#075985'],['#f472b6','#9d174d']];
function renderPowerRanks(){
 const current=teamPower(),progress=powerProgress(current),cur=progress.index,pct=progress.next===null?100:Math.round(progress.percent);
 const nextName=progress.next===null?'':TIERS[cur+1][2];
 $('#modal-body').innerHTML=`<div class="pr-wrap"><div class="pr-head"><div><p>Somme de la puissance de tes six Pokémon équipés, au maximum.</p></div><div class="pr-power"><small>PUISSANCE DE TON ÉQUIPE</small><b>${fmt(current)}</b></div></div>
 <div class="pr-stairs">${TIERS.map((tier,i)=>{const [c,d]=PR_COL[i]||PR_COL[5],st=i===cur?'cur':i>cur?'lock':'';return `<div class="pr-col"><article class="pr-card ${st}" style="--c:${c};--d:${d};height:${46+i*7}%"><div class="pr-top"><span class="pr-tag${i>cur?' o':''}">${i===cur?'RANG ACTUEL':i<cur?'ATTEINT':'À ATTEINDRE'}</span><img class="pr-badge" src="${badgeUrl(i)}" alt="" aria-hidden="true"><h3 class="pr-name">${tier[2]}</h3><small>Badge ${BADGES[i][0]}</small></div><div class="pr-bot"><div class="pr-pill"><span>Dès</span><b>${fmt(POWER_THRESHOLDS[i])}</b></div>${i===cur?(progress.next===null?'<small>Palier maximum</small>':`<div class="pr-bar"><u style="width:${pct}%"></u></div><small>${pct} % vers ${nextName}</small>`):`<small>${i<cur?'Seuil atteint':fmt(POWER_THRESHOLDS[i]-current)+' restants'}</small>`}</div></article></div>`;}).join('')}</div></div>`;
}

