function openView(next){$('#content-dialog').classList.toggle('catalog-mode',next==='pokemon'||next==='zone');$('#content-dialog').classList.toggle('settings-mode',next==='settings');$('#content-dialog').classList.toggle('wiki-mode',next==='wiki');$('#content-dialog').classList.toggle('daycare-mode',next==='daycare');$('#content-dialog').classList.toggle('shop-mode',next==='shop'||next==='items');profileToken++;$('#content-dialog').classList.remove('profile-mode');if($('#menu-drawer').open)$('#menu-drawer').close();view=next;$('#modal-title').textContent={power:'Rangs de puissance',shop:shopById(shopId).name,items:'Objets actifs',badges:'Mes badges',achievements:'Succès',defis:'Défis',elite:'Conseil des 4 & Champion',dex:'Pokédex',daycare:'Pension Pokémon',stats:'Statistiques',shinylog:'Mes chromatiques',wiki:'Wiki',quests:'Quêtes',teams:'Mes équipes',pokemon:'Mes Pokémon',map:'Carte de Kanto',history:'Dernières rencontres',odds:'Probabilités',settings:'Paramètres',arena:arenaById(arenaId).leader,zone:'Index · '+zones.find(z=>z.id===state.zone).name}[view];$('#modal-kicker').textContent={power:'TON ÉQUIPE · TES PALIERS',shop:'POKÉMART · KANTO',items:'TON SAC · EFFETS ACTIFS',badges:'CHAMPIONS D’ARÈNE · KANTO',achievements:'TES EXPLOITS · KANTO',defis:'UN TYPE TOUTES LES 6 HEURES',elite:'PLATEAU INDIGO · LIGUE',dex:'KANTO · 151 ESPÈCES',daycare:'DEUX PARENTS · UN ŒUF',stats:'TON AVENTURE EN CHIFFRES',shinylog:'HISTORIQUE DES CHROMATIQUES',wiki:'TOUTES LES RÈGLES DU JEU',quests:'OBJECTIFS DU JOUR ET DE LA SEMAINE',teams:'3 EMPLACEMENTS · CHANGEMENT EN UN CLIC',pokemon:'TA COLLECTION · TON ÉQUIPE',map:'KANTO · GÉNÉRATION I',history:'LES CINQ DERNIERS TIRAGES',odds:'KANTO · '+zones.find(z=>z.id===state.zone).name.toUpperCase(),settings:'FAÇONNE TON AVENTURE',arena:'ARÈNE · '+arenaById(arenaId).city.toUpperCase(),zone:'POKÉMON PRÉSENTS · KANTO'}[view];const body=$('#modal-body');if(view==='power'){renderPowerRanks();}else if(view==='pokemon'){collectionView=mountCollection(body,{getState:()=>state,level:lv,power:powerOf,onTeam(team){state.team=team;save();render();},onProfile:openProfile});}else if(view==='shop'){shopView=mountShop(body,{getState:()=>state,shopId,onChange(){applyInventory();save();render();renderZones();}});}else if(view==='items'){mountItems(body,{getState:()=>state,onChange(){applyInventory();save();render();}});}else if(view==='map'){body.innerHTML='<label for="region-select">Région</label><select class="regions" id="region-select"><option>Kanto — Génération I</option><option disabled>Johto — Génération II · à venir</option><option disabled>Hoenn — Génération III · à venir</option><option disabled>Sinnoh — Génération IV · à venir</option><option disabled>Unys — Génération V · à venir</option><option disabled>Kalos — Génération VI · à venir</option><option disabled>Alola — Génération VII · à venir</option><option disabled>Galar — Génération VIII · à venir</option><option disabled>Paldea — Génération IX · à venir</option></select><div class="large-map">'+mapMarkup(state.zone,busy,shopStates())+'</div><p class="map-instructions">Clique sur un rond lumineux pour voyager. Les noms apparaissent au survol ou au clavier.</p>';}else if(view==='zone'){zoneView=mountZoneIndex(body,{getState:()=>state,bonus:()=>luckTotal(),getZone:()=>zones.find(z=>z.id===state.zone),onProfile:openProfile});}else if(view==='arena'){renderArena(body);}else if(view==='badges'){renderBadges(body);}else if(view==='elite'){renderElite(body);}else if(view==='teams'){renderTeams(body);}else if(view==='dex'){dexSel=null;renderPokedex(body);}else if(view==='quests'){renderQuests(body);}else if(view==='defis'){renderDefis(body);}else if(view==='daycare'){renderDaycare(body);}else if(view==='wiki'){mountWiki(body);}else if(view==='stats'){renderStats(body);}else if(view==='shinylog'){renderShinyLog(body);}else if(view==='achievements'){renderAchievements(body);}else if(view==='history'){body.innerHTML='<div id="history"></div>';renderHistory();}else if(view==='odds'){body.innerHTML='<p>Chances actuelles du prototype, encore provisoires. Les améliorations, les légendaires à 1 sur 500 millions et les renaissances ne sont pas encore implémentés.</p><p>Une espèce ayant au moins un type favorisé reçoit un poids ×3, puis toutes les chances sont recalculées pour totaliser 100 %. Cela ne signifie pas que sa probabilité finale est multipliée exactement par trois.</p>'+zonePool(state.zone).sort((a,b)=>b.probability-a.probability).map(p=>`<div class="odds-row"><img src="${ownedSprite(p.id)}" alt=""><span>${p.name}</span><small>${odds(p)}</small><b>${(p.probability*100).toLocaleString('fr-FR',{maximumFractionDigits:2})} %</b></div>`).join('');}else{mountSettings(body,{getName:()=>state.name,onName(name){state.name=name;save();render();},onPreferences(p){state.reducedMotion=p.reducedMotion;applyPreferences();save();render();}});}if(!$('#content-dialog').open)$('#content-dialog').showModal();}
const shopStates=()=>SHOPS.map(s=>({id:s.id,x:s.at.x,y:s.at.y,name:s.name,open:shopOpen(state.kills,s),kills:shopKills(state.kills,s),need:KILLS_TO_UNLOCK,after:s.after}));
function applyInventory(){setShinyDenominator(shinyDenominator(state.inv));if(!state.inv.owned.auto)state.autoOn=false;renderAuto();}
// Mode Auto : bouton sous la zone, lance les rencontres et joue les tours seul (pause si une fenêtre est ouverte).
function renderAuto(){const b=$('#auto-toggle');if(!b)return;const owned=!!state.inv.owned.auto;b.hidden=!owned;b.setAttribute('aria-pressed',String(owned&&state.autoOn));$('#auto-state').textContent=state.autoOn?'ON':'OFF';b.classList.toggle('on',owned&&state.autoOn);}
// Tourne en continu, même menu, paramètres ou boutique ouverts ; seul un choix d'attaque à oublier le met en attente.
function autoTick(){if(!state.autoOn||!state.inv.owned.auto||!state.team.length)return;if(document.querySelector('dialog.learn[open]')||busy||learning)return;if(fight.autoStep()==='idle')roll({auto:true});}
setInterval(autoTick,650);
let shopView=null;const renderShops=()=>{renderZones();if(view==='shop'&&$('#content-dialog').open)shopView?.refresh();};
